// Notion APIレスポンスからデータ抽出してスコアリング
const notionResponse = $input.first().json;
const articles = notionResponse.results || [];

const scoredArticles = articles.map(page => {
  const props = page.properties;

  // プロパティから値を抽出（Notion API形式）
  const title = props.Title?.title[0]?.text?.content || '';
  const url = props.URL?.url || '';
  const articleId = props['Article ID']?.rich_text[0]?.text?.content || '';
  const viewCount = props['View Count']?.number || 0;
  const likeCount = props['Like Count']?.number || 0;
  const description = props.Description?.rich_text[0]?.text?.content || '';
  const categories = props.Category?.multi_select?.map(c => c.name) || [];
  const publishedDate = props['Published Date']?.date?.start || '';

  // スコア計算: PV×0.6 + いいね×0.4
  const score = (viewCount * 0.6) + (likeCount * 0.4);

  return {
    pageId: page.id,
    title,
    url,
    articleId,
    viewCount,
    likeCount,
    score,
    description,
    categories,
    publishedDate
  };
});

// スコア降順でソート
scoredArticles.sort((a, b) => b.score - a.score);

return scoredArticles.map(article => ({ json: article }));

// スコア上位10件を抽出
const articles = $input.all().map(item => item.json);

// スコア上位10件を抽出
const top10 = articles.slice(0, 10);

return [{ json: { articles: top10 } }];

