// GPT-4レスポンスをパース
const gptResponse = $input.first().json;
const content = gptResponse.choices[0].message.content;

// JSONパース
let analysis;
try {
  analysis = JSON.parse(content);
} catch (e) {
  // パースエラー時はSlack通知用にエラーをthrow
  throw new Error(`GPT-4レスポンスのJSON parse失敗: ${content}`);
}

return [{ json: analysis }];

// トピックデータ前処理: 関連記事紐付け、平均スコア計算
const analysis = $input.first().json;
const top10Articles = $('Function - トップ10記事抽出').first().json.articles;

// 各トピックに関連記事を紐付け
const topics = analysis.nextTopics.map(topic => {
  // トピックキーワードに関連する記事を抽出
  const relatedArticles = top10Articles.filter(article => {
    const matchKeyword = analysis.trendKeywords.some(keyword =>
      article.title.includes(keyword) ||
      article.description.includes(keyword) ||
      article.categories.includes(keyword)
    );
    return matchKeyword;
  });

  // 関連記事のNotion Page IDを取得
  const relatedArticleIds = relatedArticles.map(a => a.pageId);

  // 平均スコア計算
  const avgScore = relatedArticles.length > 0
    ? relatedArticles.reduce((sum, a) => sum + a.score, 0) / relatedArticles.length
    : 0;

  return {
    topic: topic.topic,
    priority: topic.priority,
    reason: topic.reason,
    trendKeywords: analysis.trendKeywords,
    relatedArticleIds,
    avgScore
  };
});

return topics.map(t => ({ json: t }));

